import{zodResolver}from"@hookform/resolvers/zod";import{useForm}from"react-hook-form";import{z}from"zod";import type{Category}from"../../types/marketplace";import type{ProductInput}from"../../types/vendor";const schema=z.object({name:z.string().trim().min(1,"Product name is required").max(200),description:z.string().max(4000),categoryId:z.coerce.number().int().positive("Category is required"),price:z.coerce.number().positive("Price must be greater than zero"),stockQuantity:z.coerce.number().int().min(0,"Stock cannot be negative"),imageUrl:z.union([z.literal(""),z.string().url("Enter a valid image URL")])});export default function ProductForm({categories,initial,busy,submitLabel,onSubmit}:{categories:Category[];initial?:ProductInput;busy:boolean;submitLabel:string;onSubmit:(input:ProductInput)=>void}){const{register,handleSubmit,formState:{errors}}=useForm<ProductInput>({resolver:zodResolver(schema),defaultValues:initial??{name:"",description:"",categoryId:0,price:0,stockQuantity:0,imageUrl:""}});const field=(name:"name"|"description"|"price"|"stockQuantity"|"imageUrl",label:string,type="text")=><label className="block text-sm font-medium">{label}<input className="mt-1 w-full rounded border p-2" type={type} step={type==="number"?"0.01":undefined} {...register(name,{valueAsNumber:type==="number"})}/><span className="text-xs text-red-700">{errors[name]?.message}</span></label>;return <form className="space-y-4 rounded-xl border bg-white p-6" onSubmit={handleSubmit(onSubmit)}>{field("name","Product name")}<label className="block text-sm font-medium">Description<textarea className="mt-1 min-h-28 w-full rounded border p-2" {...register("description")}/><span className="text-xs text-red-700">{errors.description?.message}</span></label><label className="block text-sm font-medium">Category<select className="mt-1 w-full rounded border p-2" {...register("categoryId",{valueAsNumber:true})}><option value="0">Select category</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><span className="text-xs text-red-700">{errors.categoryId?.message}</span></label><div className="grid gap-4 sm:grid-cols-2">{field("price","Price","number")}{field("stockQuantity","Stock quantity","number")}</div>{field("imageUrl","Image URL")}<p className="text-xs text-slate-500">MarketHub currently accepts image URLs; file upload is not supported by the backend.</p><button className="w-full rounded bg-brand-700 px-4 py-3 font-semibold text-white disabled:bg-slate-300" disabled={busy}>{busy?"Saving…":submitLabel}</button></form>}
